insert into levels (id, title, sort) values ('foundations', 'Foundations', 1) on conflict (id) do nothing;
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('pillars', 'foundations', 'The Five Pillars', 'What Islam is built on', '#2F7D5B', true, 1) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('pillars-1', 'pillars', 'Built on five', 'The Prophet ﷺ said that Islam is built on five: the testimony of faith (shahada), prayer (salah), charity (zakat), fasting in Ramadan (sawm) and pilgrimage to the House (hajj).', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'choice', '{"type":"choice","prompt":"How many pillars is Islam built on?","options":["Three","Five","Six","Seven"],"answer":1,"explain":"Islam is built on five pillars.","source":{"kind":"hadith","reference":"Sahih al-Bukhari 8, Sahih Muslim 16"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'match', '{"type":"match","prompt":"Match each pillar to its meaning","pairs":[["Shahada","Testimony of faith"],["Salah","Prayer"],["Zakat","Obligatory charity"],["Sawm","Fasting"],["Hajj","Pilgrimage"]],"explain":"These five together are the pillars of Islam."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'choice', '{"type":"choice","prompt":"Which of these is NOT one of the five pillars?","options":["Fasting in Ramadan","Zakat","Reading the whole Quran each month","Hajj"],"answer":2,"explain":"Reading the Quran is highly rewarded, but the five pillars are shahada, salah, zakat, sawm and hajj."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'order', '{"type":"order","prompt":"Put the pillars in the order the hadith mentions them","items":["Shahada","Salah","Zakat","Hajj","Sawm"],"explain":"In the narration of Sahih al-Bukhari 8 the order is shahada, salah, zakat, hajj, then fasting in Ramadan. Other narrations mention fasting before hajj.","source":{"kind":"hadith","reference":"Sahih al-Bukhari 8"}}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('pillars-1', 'choice', '{"type":"choice","minLevel":"intermediate","prompt":"Which Companion narrated the hadith \"Islam is built on five\"?","options":["Abu Hurayrah","Abdullah ibn Umar","Anas ibn Malik","Aisha"],"answer":1,"explain":"It is narrated by Abdullah ibn Umar (may Allah be pleased with them both).","source":{"kind":"hadith","reference":"Sahih al-Bukhari 8, Sahih Muslim 16"}}'::jsonb, 5);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('pillars-2', 'pillars', 'The shahada', 'The shahada is: "Ash-hadu an la ilaha illa Allah, wa ash-hadu anna Muhammadan rasul Allah." I bear witness that there is no god but Allah, and I bear witness that Muhammad is the Messenger of Allah.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('pillars-2', 'choice', '{"type":"choice","prompt":"What does \"la ilaha illa Allah\" mean?","options":["Allah is the greatest","There is no god but Allah","All praise is for Allah","In the name of Allah"],"answer":1,"explain":"\"La ilaha illa Allah\" means there is no god worthy of worship except Allah."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('pillars-2', 'order', '{"type":"order","prompt":"Build the shahada","items":["Ash-hadu","an la ilaha","illa Allah,","wa ash-hadu anna","Muhammadan","rasul Allah"],"explain":"This is the full testimony of faith."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('pillars-2', 'choice', '{"type":"choice","prompt":"The second part of the shahada is a testimony about whom?","options":["Prophet Ibrahim","Prophet Musa","Prophet Muhammad ﷺ","Angel Jibril"],"answer":2,"explain":"The second part bears witness that Muhammad ﷺ is the Messenger of Allah."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('pillars-2', 'match', '{"type":"match","prompt":"Match the Arabic to its meaning","pairs":[["Ash-hadu","I bear witness"],["La ilaha","There is no god"],["Illa Allah","Except Allah"],["Rasul","Messenger"]],"explain":"Knowing the meaning makes the words come alive."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('pillars-3', 'pillars', 'Salah and zakat', 'Muslims pray five times every day. Zakat is a yearly charity: 2.5% of savings that stay above a minimum amount (the nisab) for a full lunar year, given to those who are eligible.', 3, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'choice', '{"type":"choice","prompt":"How many obligatory prayers are there each day?","options":["Three","Four","Five","Seven"],"answer":2,"explain":"There are five daily prayers: Fajr, Dhuhr, Asr, Maghrib and Isha."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'order', '{"type":"order","prompt":"Put the daily prayers in order, starting at dawn","items":["Fajr","Dhuhr","Asr","Maghrib","Isha"],"explain":"Fajr is at dawn, Dhuhr after midday, Asr in the afternoon, Maghrib at sunset and Isha at night."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'choice', '{"type":"choice","prompt":"What share of eligible savings is paid as zakat?","options":["1%","2.5%","10%","20%"],"answer":1,"explain":"Zakat on savings is 2.5% once they stay above the nisab for a lunar year."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'choice', '{"type":"choice","prompt":"In the Quran, which pillar is very often mentioned together with prayer?","options":["Hajj","Zakat","Fasting","Shahada"],"answer":1,"explain":"Allah often says \"establish prayer and give zakat\", for example in Al-Baqarah 2:43.","source":{"kind":"quran","reference":"Quran 2:43"}}'::jsonb, 4);
insert into exercises (lesson_id, type, body, sort) values ('pillars-3', 'choice', '{"type":"choice","minLevel":"advanced","prompt":"Over what period must savings stay above the nisab before zakat is due?","options":["One month","One lunar year (hawl)","Ramadan only","Five years"],"answer":1,"explain":"Zakat on wealth is due once it has stayed at or above the nisab for a full lunar year, called the hawl."}'::jsonb, 5);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('pillars-4', 'pillars', 'Fasting and hajj', 'In Ramadan, Muslims fast from dawn (Fajr) until sunset (Maghrib), leaving food, drink and marital relations. Hajj is the pilgrimage to Makkah, required once in a lifetime for those who are able.', 4, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('pillars-4', 'choice', '{"type":"choice","prompt":"A fast in Ramadan lasts from…","options":["Sunrise to noon","Dawn to sunset","Midnight to midnight","Sunset to dawn"],"answer":1,"explain":"The fast begins at dawn (Fajr) and ends at sunset (Maghrib)."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('pillars-4', 'choice', '{"type":"choice","prompt":"Why did Allah prescribe fasting, according to Al-Baqarah 2:183?","options":["To lose weight","So that you may attain taqwa","To save money","To travel"],"answer":1,"explain":"\"Fasting is prescribed for you… so that you may become mindful of Allah (taqwa).\"","source":{"kind":"quran","reference":"Quran 2:183"}}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('pillars-4', 'choice', '{"type":"choice","prompt":"How often is hajj required?","options":["Every year","Every five years","Once in a lifetime, for those able","Never required"],"answer":2,"explain":"Hajj is an obligation once in a lifetime for those who are able to make the journey.","source":{"kind":"quran","reference":"Quran 3:97"}}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('pillars-4', 'match', '{"type":"match","prompt":"Match each pillar to when it happens","pairs":[["Sawm","The month of Ramadan"],["Hajj","The month of Dhul Hijjah"],["Salah","Five times every day"],["Zakat","Once a lunar year"]],"explain":"Each pillar has its own time."}'::jsonb, 4);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('prayer', 'foundations', 'How to Pray', 'Wudu and the steps of salah', '#2E6FA3', true, 2) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('prayer-1', 'prayer', 'Wudu', 'Wudu is the washing done before prayer. The Quran (5:6) commands washing the face, the arms up to the elbows, wiping the head, and washing the feet up to the ankles. The Sunnah adds rinsing the mouth and nose, and starting with the hands.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('prayer-1', 'order', '{"type":"order","prompt":"Put the steps of wudu in order","items":["Intention and Bismillah","Wash the hands","Rinse the mouth","Rinse the nose","Wash the face","Wash the arms to the elbows","Wipe the head and ears","Wash the feet to the ankles"],"explain":"This is the common order of wudu taught from the Sunnah.","source":{"kind":"quran","reference":"Quran 5:6"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('prayer-1', 'choice', '{"type":"choice","prompt":"Up to where are the arms washed in wudu?","options":["The wrists","The elbows","The shoulders","Only the fingers"],"answer":1,"explain":"The arms are washed up to and including the elbows.","source":{"kind":"quran","reference":"Quran 5:6"}}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('prayer-1', 'choice', '{"type":"choice","prompt":"Which part is wiped, not washed?","options":["The face","The feet","The head","The arms"],"answer":2,"explain":"The head is wiped with wet hands."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('prayer-2', 'prayer', 'Prayers and rak‘ahs', 'Each prayer is made of units called rak‘ahs. Fajr has 2, Dhuhr 4, Asr 4, Maghrib 3 and Isha 4. These are the obligatory (fard) rak‘ahs.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('prayer-2', 'match', '{"type":"match","prompt":"Match each prayer to its fard rak‘ahs","pairs":[["Fajr","2"],["Maghrib","3"],["Dhuhr","4"]],"explain":"Asr and Isha also have 4 fard rak‘ahs."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('prayer-2', 'choice', '{"type":"choice","prompt":"How many fard rak‘ahs does Maghrib have?","options":["2","3","4","5"],"answer":1,"explain":"Maghrib is the only daily prayer with 3 rak‘ahs."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('prayer-2', 'choice', '{"type":"choice","prompt":"How many fard rak‘ahs are there in a full day?","options":["15","17","19","20"],"answer":1,"explain":"2 + 4 + 4 + 3 + 4 = 17."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('prayer-2', 'choice', '{"type":"choice","minLevel":"intermediate","prompt":"Which two prayers may a traveller combine at the time of either one, in most schools?","options":["Fajr and Dhuhr","Dhuhr and Asr","Maghrib and Fajr","Asr and Maghrib"],"answer":1,"explain":"Dhuhr with Asr, and Maghrib with Isha, may be combined when travelling in the Shafi‘i, Maliki and Hanbali schools. The Hanafi school allows real combining only at Arafah and Muzdalifah during Hajj."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('prayer-3', 'prayer', 'Steps of a rak‘ah', 'A rak‘ah moves through standing, bowing (ruku‘), rising, prostrating (sujud), sitting, and prostrating again. The prayer opens with "Allahu Akbar" and ends with the tashahhud and the salam.', 3, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('prayer-3', 'order', '{"type":"order","prompt":"Put the first rak‘ah in order","items":["Takbir: \"Allahu Akbar\"","Recite Al-Fatihah","Ruku‘ (bow)","Stand up straight","First sujud","Sit briefly","Second sujud"],"explain":"This is the shape of every rak‘ah. A short surah is usually recited after Al-Fatihah in the first two rak‘ahs."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('prayer-3', 'choice', '{"type":"choice","prompt":"Which surah is recited in every rak‘ah?","options":["Al-Ikhlas","Al-Fatihah","An-Nas","Al-Kawthar"],"answer":1,"explain":"Al-Fatihah is recited in every rak‘ah of every prayer."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('prayer-3', 'choice', '{"type":"choice","prompt":"How does the prayer end?","options":["With a sujud","With the salam to the right and left","With ruku‘","By standing up"],"answer":1,"explain":"After the final tashahhud, the prayer ends with \"As-salamu alaykum wa rahmatullah\" to the right and left."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('prayer-4', 'prayer', 'What to say', 'In ruku‘ say "Subhana Rabbiya al-‘Azim" (Glory be to my Lord, the Magnificent). In sujud say "Subhana Rabbiya al-A‘la" (Glory be to my Lord, the Most High).', 4, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('prayer-4', 'match', '{"type":"match","prompt":"Match each position to what is said","pairs":[["Opening","Allahu Akbar"],["Ruku‘","Subhana Rabbiya al-‘Azim"],["Sujud","Subhana Rabbiya al-A‘la"],["Ending","As-salamu alaykum wa rahmatullah"]],"explain":"These are the core words of each position.","source":{"kind":"hadith","reference":"Sahih Muslim 772"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('prayer-4', 'choice', '{"type":"choice","prompt":"What does \"Subhana Rabbiya al-A‘la\" mean?","options":["Allah is the greatest","Glory be to my Lord, the Most High","All praise is for Allah","Allah hears whoever praises Him"],"answer":1,"explain":"It is said in sujud, when we are lowest to the ground."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('prayer-4', 'choice', '{"type":"choice","prompt":"When rising from ruku‘, what is said?","options":["Sami‘a Allahu liman hamidah","Bismillah","Astaghfirullah","Subhan Allah"],"answer":0,"explain":"\"Allah hears whoever praises Him\", followed by \"Rabbana wa laka al-hamd\"."}'::jsonb, 3);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('seerah', 'foundations', 'The Seerah', 'The life of the Prophet ﷺ', '#1F7A8C', false, 3) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('seerah-1', 'seerah', 'Early life in Makkah', 'Muhammad ﷺ was born in Makkah in the Year of the Elephant, around 570 CE. He grew up an orphan and became known as al-Amin, the trustworthy.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('seerah-1', 'choice', '{"type":"choice","prompt":"What nickname did the people of Makkah give the Prophet ﷺ?","options":["As-Siddiq","Al-Amin","Al-Faruq","Saifullah"],"answer":1,"explain":"Al-Amin means the trustworthy. Even his enemies trusted him with their belongings."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('seerah-1', 'truefalse', '{"type":"truefalse","statement":"The Prophet ﷺ was raised by his father Abdullah.","answer":false,"explain":"His father died before he was born. He was raised by his grandfather Abd al-Muttalib and then his uncle Abu Talib."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('seerah-1', 'fill', '{"type":"fill","sentence":"The Prophet ﷺ was born in the Year of the ___.","options":["Elephant","Camel","Flood","Hijrah"],"answer":0,"explain":"It is named after the army with elephants that marched on Makkah that year (Surah Al-Fil).","source":{"kind":"quran","reference":"Quran 105"}}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('seerah-1', 'order', '{"type":"order","prompt":"Put these events in order","items":["Born in Makkah","His mother Aminah passes away","Raised by Abu Talib","Marries Khadijah"],"explain":"This is the order of his early life."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('seerah-2', 'seerah', 'The first revelation', 'At the age of 40, while in the cave of Hira, the angel Jibril came to the Prophet ﷺ and said "Iqra" (Read). The first verses revealed were the opening of Surah Al-Alaq.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('seerah-2', 'choice', '{"type":"choice","prompt":"In which cave did the first revelation come?","options":["Thawr","Hira","Uhud","Kahf"],"answer":1,"explain":"The first revelation came in the cave of Hira.","source":{"kind":"hadith","reference":"Sahih al-Bukhari 3"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('seerah-2', 'fill', '{"type":"fill","sentence":"The first word Jibril said was \"___\", which means \"Read\".","options":["Iqra","Qul","Bismillah","Salam"],"answer":0,"explain":"Surah Al-Alaq begins: \"Read in the name of your Lord who created.\"","source":{"kind":"quran","reference":"Quran 96:1"}}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('seerah-2', 'truefalse', '{"type":"truefalse","statement":"Khadijah was the first person to believe in the Prophet ﷺ.","answer":true,"explain":"Khadijah was the first to believe in him and supported him with her wealth and comfort."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('seerah-2', 'choice', '{"type":"choice","prompt":"How old was the Prophet ﷺ when revelation began?","options":["25","33","40","53"],"answer":2,"explain":"He was 40 years old."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('seerah-3', 'seerah', 'The Hijrah', 'After 13 years of calling people to Islam in Makkah through hardship and persecution, the Prophet ﷺ migrated to Madinah with Abu Bakr in 622 CE. This journey is the Hijrah.', 3, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('seerah-3', 'choice', '{"type":"choice","prompt":"Who travelled with the Prophet ﷺ on the Hijrah?","options":["Umar","Abu Bakr","Uthman","Bilal"],"answer":1,"explain":"Abu Bakr as-Siddiq was his companion on the journey.","source":{"kind":"quran","reference":"Quran 9:40"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('seerah-3', 'truefalse', '{"type":"truefalse","statement":"They hid in the cave of Hira during the Hijrah.","answer":false,"explain":"They hid in the cave of Thawr. Hira is where the first revelation came."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('seerah-3', 'match', '{"type":"match","prompt":"Match each name to its role","pairs":[["Ansar","The people of Madinah who helped"],["Muhajirun","The Muslims who migrated"],["An-Najashi","King who protected Muslims in Abyssinia"]],"explain":"The Prophet ﷺ joined the Muhajirun and Ansar as brothers in Madinah."}'::jsonb, 3);
insert into exercises (lesson_id, type, body, sort) values ('seerah-3', 'fill', '{"type":"fill","sentence":"The Islamic calendar starts from the year of the ___.","options":["Hijrah","Birth of the Prophet","First revelation","Conquest of Makkah"],"answer":0,"explain":"The Hijri calendar counts from the Hijrah, a decision made during the caliphate of Umar."}'::jsonb, 4);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('seerah-4', 'seerah', 'Madinah and the final years', 'In Madinah the Prophet ﷺ built his masjid and a community. Makkah was opened in 8 AH with forgiveness, he performed the Farewell Hajj in 10 AH, and he passed away in 11 AH at the age of 63.', 4, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('seerah-4', 'order', '{"type":"order","prompt":"Put these events in order","items":["Building the masjid in Madinah","Battle of Badr","Opening of Makkah","Farewell Hajj"],"explain":"Masjid (1 AH), Badr (2 AH), Makkah (8 AH), Farewell Hajj (10 AH)."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('seerah-4', 'truefalse', '{"type":"truefalse","statement":"When the Prophet ﷺ entered Makkah, he forgave the people who had persecuted him.","answer":true,"explain":"He forgave them, showing mercy at the moment of victory."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('seerah-4', 'choice', '{"type":"choice","prompt":"How old was the Prophet ﷺ when he passed away?","options":["40","53","63","70"],"answer":2,"explain":"He passed away at 63, in 11 AH."}'::jsonb, 3);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('sahaba', 'foundations', 'The Companions', 'Stories of the Sahaba', '#5B7F2E', false, 4) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('sahaba-1', 'sahaba', 'Abu Bakr as-Siddiq', 'Abu Bakr was the Prophet’s closest friend, the first free adult man to accept Islam, his companion on the Hijrah, and the first caliph after him.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('sahaba-1', 'choice', '{"type":"choice","prompt":"What does \"as-Siddiq\" mean?","options":["The brave","The one who affirms the truth","The generous","The scholar"],"answer":1,"explain":"He earned the title by believing the Prophet ﷺ immediately about the Isra’ and Mi‘raj."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-1', 'truefalse', '{"type":"truefalse","statement":"Abu Bakr freed Bilal from slavery.","answer":true,"explain":"Abu Bakr bought Bilal’s freedom from Umayyah ibn Khalaf."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-1', 'fill', '{"type":"fill","sentence":"Abu Bakr was the ___ caliph of the Muslims.","options":["first","second","third","fourth"],"answer":0,"explain":"The four rightly guided caliphs are Abu Bakr, Umar, Uthman and Ali."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('sahaba-2', 'sahaba', 'Umar ibn al-Khattab', 'Umar was once a fierce enemy of Islam. He accepted Islam after hearing the Quran, became known as al-Faruq, and as the second caliph was famous for his justice.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('sahaba-2', 'choice', '{"type":"choice","prompt":"Which surah was Umar reading when his heart softened?","options":["Al-Fatihah","Ta-Ha","Yasin","Al-Mulk"],"answer":1,"explain":"It was Surah Ta-Ha, at his sister’s house."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-2', 'match', '{"type":"match","prompt":"Match the Companion to his title","pairs":[["Abu Bakr","As-Siddiq"],["Umar","Al-Faruq"],["Uthman","Dhun-Nurayn"]],"explain":"Al-Faruq means the one who distinguishes truth from falsehood."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-2', 'truefalse', '{"type":"truefalse","statement":"Umar was the second caliph.","answer":true,"explain":"He became caliph after Abu Bakr."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('sahaba-3', 'sahaba', 'Uthman and Ali', 'Uthman ibn Affan, the third caliph, was known for his modesty and generosity and gathered the Quran into one standard copy. Ali ibn Abi Talib, the Prophet’s cousin, was the fourth caliph.', 3, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('sahaba-3', 'fill', '{"type":"fill","sentence":"Uthman was called Dhun-Nurayn because he married two of the Prophet’s ___.","options":["daughters","cousins","sisters","aunts"],"answer":0,"explain":"He married Ruqayyah and, after her death, Umm Kulthum."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-3', 'choice', '{"type":"choice","prompt":"Who slept in the Prophet’s bed on the night of the Hijrah?","options":["Abu Bakr","Umar","Ali","Bilal"],"answer":2,"explain":"Ali stayed behind and slept in his bed so the Prophet ﷺ could leave safely."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-3', 'order', '{"type":"order","prompt":"Put the four rightly guided caliphs in order","items":["Abu Bakr","Umar","Uthman","Ali"],"explain":"These four led the Muslims after the Prophet ﷺ."}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('sahaba-4', 'sahaba', 'Bilal ibn Rabah', 'Bilal was an enslaved man in Makkah who held on to Islam under torture, repeating "Ahad, Ahad" (One, One). He was freed and became the first mu’adhdhin of Islam.', 4, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('sahaba-4', 'fill', '{"type":"fill","sentence":"Under torture, Bilal kept saying \"___\", meaning Allah is One.","options":["Ahad, Ahad","Akbar, Akbar","Salam, Salam","Haqq, Haqq"],"answer":0,"explain":"Ahad means One. He refused to give up tawhid."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-4', 'choice', '{"type":"choice","prompt":"What special role did Bilal have in Madinah?","options":["Treasurer","First mu’adhdhin","Army general","Judge"],"answer":1,"explain":"He was the first to call the adhan."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('sahaba-4', 'truefalse', '{"type":"truefalse","statement":"In Islam, a person is honoured by their lineage more than their taqwa.","answer":false,"explain":"\"The most noble of you in the sight of Allah is the most righteous of you.\"","source":{"kind":"quran","reference":"Quran 49:13"}}'::jsonb, 3);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('iman', 'foundations', 'The Articles of Faith', 'Iman and the hadith of Jibril', '#7A4FA3', false, 5) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('iman-1', 'iman', 'Six articles', 'When Jibril asked the Prophet ﷺ about iman, he answered: to believe in Allah, His angels, His books, His messengers, the Last Day, and to believe in the divine decree (qadar), its good and its bad.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('iman-1', 'choice', '{"type":"choice","prompt":"How many articles of faith are mentioned in the hadith of Jibril?","options":["Four","Five","Six","Seven"],"answer":2,"explain":"There are six: Allah, the angels, the books, the messengers, the Last Day, and qadar.","source":{"kind":"hadith","reference":"Sahih Muslim 8"}}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('iman-1', 'choice', '{"type":"choice","prompt":"Which of these is an article of faith rather than a pillar of Islam?","options":["Fasting","Belief in the angels","Zakat","Hajj"],"answer":1,"explain":"The pillars of Islam are actions. The articles of faith are what a Muslim believes."}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('iman-1', 'match', '{"type":"match","prompt":"Match the term to its meaning","pairs":[["Islam","Submission through outward acts"],["Iman","Faith in the heart"],["Ihsan","Worshipping Allah as if you see Him"]],"explain":"The hadith of Jibril teaches all three levels of the religion.","source":{"kind":"hadith","reference":"Sahih Muslim 8"}}'::jsonb, 3);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('iman-2', 'iman', 'Books and messengers', 'Allah sent revealed books with His messengers: the Tawrah to Musa, the Zabur to Dawud, the Injil to Isa, and the Quran to Muhammad ﷺ, the final messenger.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('iman-2', 'match', '{"type":"match","prompt":"Match each book to its messenger","pairs":[["Tawrah","Musa"],["Zabur","Dawud"],["Injil","Isa"],["Quran","Muhammad ﷺ"]],"explain":"Belief in all of Allah’s revealed books is part of iman."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('iman-2', 'choice', '{"type":"choice","prompt":"Which angel brought revelation to the prophets?","options":["Mika’il","Jibril","Malik","Ridwan"],"answer":1,"explain":"Jibril brought the revelation, and is described in the Quran as the trustworthy spirit (26:193).","source":{"kind":"quran","reference":"Quran 26:193"}}'::jsonb, 2);
insert into exercises (lesson_id, type, body, sort) values ('iman-2', 'choice', '{"type":"choice","minLevel":"advanced","prompt":"What does \"khatam an-nabiyyin\" in Al-Ahzab 33:40 mean?","options":["The first of the prophets","The seal of the prophets","The friend of the prophets","The son of the prophets"],"answer":1,"explain":"Muhammad ﷺ is the seal of the prophets: no prophet comes after him.","source":{"kind":"quran","reference":"Quran 33:40"}}'::jsonb, 3);
insert into units (id, level_id, title, subtitle, color, foundation, sort) values ('madhabs', 'foundations', 'Prayer in the Four Madhabs', 'Where the schools agree and differ', '#A35A2E', false, 6) on conflict (id) do update set title = excluded.title, subtitle = excluded.subtitle;
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('madhabs-1', 'madhabs', 'The four schools', 'The four Sunni schools of fiqh are named after Imam Abu Hanifah, Imam Malik, Imam ash-Shafi‘i and Imam Ahmad ibn Hanbal. They agree on the foundations and differ in some details, each with evidence. Follow a qualified teacher in your school.', 1, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('madhabs-1', 'match', '{"type":"match","prompt":"Match each school to its founding imam","pairs":[["Hanafi","Abu Hanifah"],["Maliki","Malik ibn Anas"],["Shafi‘i","Muhammad ibn Idris ash-Shafi‘i"],["Hanbali","Ahmad ibn Hanbal"]],"explain":"All four are respected schools of Sunni fiqh."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('madhabs-1', 'choice', '{"type":"choice","prompt":"Which school treats witr as wajib (necessary) rather than sunnah?","options":["Hanafi","Maliki","Shafi‘i","Hanbali"],"answer":0,"explain":"The Hanafi school holds witr to be wajib. The other three hold it to be a highly stressed sunnah."}'::jsonb, 2);
insert into lessons (id, unit_id, title, teach, sort, review_status) values ('madhabs-2', 'madhabs', 'Asr time and raising the hands', 'For Asr, the Hanafi school begins the time when an object’s shadow is twice its length, while the other three schools begin it when the shadow equals its length. On raising the hands at ruku‘, the Shafi‘i and Hanbali schools do it, while the Hanafi school, and the Maliki school in its well-known view, raise them only at the opening takbir.', 2, 'draft') on conflict (id) do update set title = excluded.title, teach = excluded.teach;
insert into exercises (lesson_id, type, body, sort) values ('madhabs-2', 'choice', '{"type":"choice","prompt":"In the Hanafi school, Asr begins when a shadow is…","options":["Equal to the object","Twice the object","Half the object","Gone"],"answer":1,"explain":"This is why prayer apps offer a separate Hanafi Asr setting."}'::jsonb, 1);
insert into exercises (lesson_id, type, body, sort) values ('madhabs-2', 'match', '{"type":"match","prompt":"Raising the hands when going into ruku‘","pairs":[["Shafi‘i","Raises the hands"],["Hanbali","Also raises the hands"],["Hanafi","Only at the opening takbir"]],"explain":"Both practices have evidence in the Sunnah. Each school weighed the narrations differently."}'::jsonb, 2);
